// Independent public HTML/JSON adapter. Protocol reference: keiyoushi/extensions-source
// dbf6c05d6a9520c60533f1626616263522bbe71a/src/zh/bh3 (Apache-2.0).
// No website JavaScript, app bridge, auth or purchase flow is executed.
var BASE = 'https://comic.bh3.com';
function fail(message) { throw new Error('崩坏3官方漫画：' + message); }
function id(value) {
  value = String(value == null ? '' : value);
  if (!/^\d{1,12}$/.test(value)) fail('作品或章节编号无效');
  return value;
}
function ownPath(url, chapter) {
  var expression = chapter ? /^https:\/\/comic\.bh3\.com\/book\/(\d{1,12})\/(\d{1,12})(?:[?#].*)?$/ : /^https:\/\/comic\.bh3\.com\/book\/(\d{1,12})\/?(?:[?#].*)?$/;
  var m = String(url || '').match(expression);
  if (!m) fail('地址不属于当前官方来源');
  return chapter ? [id(m[1]), id(m[2])] : id(m[1]);
}
async function fetchText(url) {
  var response = await triomi.fetch(url, {headers:{Referer:BASE + '/'}});
  if (response.status !== 200) fail('HTTP ' + response.status);
  if (response.url && !/^https:\/\/comic\.bh3\.com\//.test(response.url)) fail('来源跳转到了非官方地址');
  var text = response.body;
  if (typeof text !== 'string' || !text.trim()) fail('服务器返回空内容');
  if (text.length > 2097152) fail('页面超出安全大小');
  if (/cf-chl-|challenge-platform|captcha|人机验证|访问过于频繁|Just a moment/i.test(text)) fail('站点要求验证或限制访问');
  return text;
}
async function value(html, selector) {
  var rows = await triomi.select(html, selector, {v:{selector:'.'}});
  return rows.length ? String(rows[0].v || '').trim() : '';
}
function imageUrl(value) {
  if (typeof value !== 'string') fail('图片地址缺失');
  if (value.indexOf('//') === 0) value = 'https:' + value;
  if (!/^https:\/\/[^\s/?#@]+\/[^\s]*$/.test(value)) fail('图片地址不是有效HTTPS地址');
  return value;
}
async function catalog() {
  var html = await fetchText(BASE + '/book');
  var cards = await triomi.select(html, 'a[href*="book"]', {
    id:{selector:'div.container',attr:'id'}, title:{selector:'div.container-title'},
    cover:{selector:'img',attr:'src',absolute:true}
  }, BASE);
  var result = [], seen = {};
  for (var i = 0; i < cards.length; i++) {
    var card = cards[i];
    if (!card.id && !card.title) continue;
    var bid = id(card.id);
    if (!card.title) fail('官方作品标题缺失');
    if (seen[bid]) continue;
    seen[bid] = true;
    result.push({remoteId:bid,title:card.title,url:BASE + '/book/' + bid,coverUrl:imageUrl(card.cover)});
    if (result.length > 200) fail('目录数量超出安全限制');
  }
  if (!result.length) fail('未找到官方漫画目录，页面结构可能变化');
  return result;
}
async function discover(url, page) { return page > 1 ? [] : catalog(); }
async function search(keyword, page) {
  if (page > 1 || !String(keyword || '').trim()) return [];
  var query = String(keyword).trim().toLowerCase();
  return (await catalog()).filter(function(item) {return item.title.toLowerCase().indexOf(query) !== -1;});
}
async function detail(url, item) {
  var bid = ownPath(url, false), pageUrl = BASE + '/book/' + bid;
  var html = await fetchText(pageUrl), title = await value(html, 'div.title');
  if (!title) fail('作品详情标题缺失');
  var covers = await triomi.select(html, 'img.cover', {url:{selector:'.',attr:'src',absolute:true}}, BASE);
  if (!covers.length) fail('作品封面缺失');
  var rows;
  try { rows = JSON.parse(await fetchText(pageUrl + '/get_chapter')); }
  catch (error) { fail('章节目录无法读取：' + error.message); }
  if (!Array.isArray(rows) || !rows.length || rows.length > 2000) fail('没有公开章节或章节目录格式变化');
  var chapters = [], seen = {};
  for (var i = 0; i < rows.length; i++) {
    var row = rows[i];
    if (!row || typeof row !== 'object' || id(row.bookid) !== bid) fail('章节不属于当前作品');
    var cid = id(row.chapterid);
    if (seen[cid]) continue;
    seen[cid] = true;
    if (typeof row.title !== 'string' || !row.title.trim()) fail('章节标题缺失');
    chapters.push({remoteId:bid + '/' + cid,title:row.title,url:pageUrl + '/' + cid,number:Number(cid)});
  }
  chapters.sort(function(a,b){return a.number-b.number;});
  return {item:{remoteId:bid,title:title,url:pageUrl,coverUrl:imageUrl(covers[0].url),author:'崩坏3官方',description:await value(html,'div.detail_info1')},chapters:chapters};
}
async function content(url, chapter) {
  var parts = ownPath(url, true), html = await fetchText(BASE + '/book/' + parts[0] + '/' + parts[1]);
  var rows = await triomi.select(html, 'img.lazy.comic_img', {url:{selector:'.',attr:'data-original',absolute:true}}, BASE);
  if (!rows.length || rows.length > 500) fail('没有公开图片或章节需要额外权限');
  return {images:rows.map(function(row){return imageUrl(row.url);})};
}
